.cw {
  padding: 16px 20px;
  max-width: 100%;
}

.cw__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 12px;
}

.cw__title {
  margin: 0;
  font: var(--g-text-subheader-2-font, 600 18px/24px system-ui, sans-serif);
  color: var(--g-color-text-primary);
}

.cw__body {
  position: relative;
  min-width: 0;
}

.cw__loader {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 100%;
}

/* Движок заполняет область графика целиком. */
.cw-engine,
.cw-engine > .chartkit-theme_common {
  height: 100%;
  width: 100%;
}

.cw-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 20px;
  list-style: none;
  margin: 0 0 12px;
  padding: 0;
}

.cw-legend__item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  color: var(--g-color-text-secondary);
}

.cw-legend__swatch {
  width: 10px;
  height: 10px;
  border-radius: 2px;
  flex: none;
}

.cw-legend__name {
  color: var(--g-color-text-primary);
}

.cw-legend__value {
  font-variant-numeric: tabular-nums;
  color: var(--g-color-text-secondary);
}

