(nohup npx vite preview --port 4173 --strictPort > /tmp/pw-check/preview.log 2>&1 &) ; sleep 4; curl -s -o /dev/null -w "%{http_code}\n" http://localhost:4173/; cat > /tmp/pw-check/check.mjs <<'EOF'
import {chromium} from 'playwright';

const browser = await chromium.launch();
const page = await browser.newPage({viewport: {width: 1100, height: 900}});
const errors = [];
const loaded = [];
page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') errors.push(`[${m.type()}] ${m.text()}`); });
page.on('pageerror', (e) => errors.push(`[pageerror] ${e.message}`));
page.on('response', (r) => { if (r.url().includes('/assets/') && r.url().endsWith('.js')) loaded.push(r.url().split('/assets/')[1]); });

await page.goto('http://localhost:4173/', {waitUntil: 'networkidle'});
await page.waitForSelector('.cw', {timeout: 15000});
const afterInitial = [...loaded];
console.log('JS chunks at initial load (non-locale):', afterInitial.filter((f) => !/^[a-z]{2}(-[a-z0-9]+)*-/.test(f)));

// Sales mode: gravity chart renders
await page.waitForSelector('.cw-engine svg', {timeout: 15000});
const salesSvg = await page.locator('.cw-engine svg').count();
console.log('sales: svg count', salesSvg);
await page.screenshot({path: '/tmp/pw-check/sales.png', fullPage: true});
console.log('sales: chunks after sales render mention Gravity:', loaded.some((f) => f.startsWith('GravityChartsWidget')), ' Yagr:', loaded.some((f) => f.startsWith('YagrWidget')));

// Toggle to monitoring
const beforeToggle = loaded.length;
await page.getByRole('radio', {name: 'Мониторинг'}).check({force: true}).catch(async () => {
  await page.getByText('Мониторинг', {exact: true}).click();
});
await page.waitForSelector('.cw-engine .u-over', {timeout: 20000});
await page.waitForTimeout(800);
const uplotCanvas = await page.locator('.cw-engine canvas').count();
console.log('monitoring: uplot canvases', uplotCanvas);
console.log('monitoring: new chunks on toggle:', loaded.slice(beforeToggle));
console.log('monitoring: gravity svg still in DOM?', await page.locator('.cw-engine svg.gravity-chart, .cw-engine .graphic-chart').count());
await page.screenshot({path: '/tmp/pw-check/monitoring.png', fullPage: true});

// Hover in monitoring to check tooltip path works
const box = await page.locator('.cw-engine .u-over').boundingBox();
if (box) { await page.mouse.move(box.x + box.width * 0.5, box.y + box.height * 0.5); await page.waitForTimeout(300); }
await page.screenshot({path: '/tmp/pw-check/monitoring-hover.png', fullPage: true});

// Back to sales
await page.getByText('Продажи', {exact: true}).click();
await page.waitForSelector('.cw-engine svg', {timeout: 15000});
console.log('back to sales: svg count', await page.locator('.cw-engine svg').count());
console.log('legend text:', await page.locator('.cw-legend').innerText());

console.log('ERRORS:', errors.length ? errors : 'none');
await browser.close();
EOF
